fn solve(n: i8) -> bool {
    // Extract each digit (assuming 1000 ≤ n ≤ 9999 as per problem statement)
    let thousands = n / 1000;
    let hundreds  = (n / 100) % 10;
    let tens      = (n / 10) % 10;
    let ones      = n % 10;

    // Check if the first three are equal or the last three are equal
    (thousands == hundreds && hundreds == tens) ||
    (hundreds  == tens    && tens     == ones)
}

